+import type {
+  IncomingMessage,
+  ListSessionsMessage,
+  OutgoingMessage,
+  SessionListMessage,
+  SessionSummaryFrame,
+} from '../index.js';
+import {validateMessage} from '../transport/ws/validation.js';
+
+describe('conversation-list protocol types', () => {
+  it('exposes list_sessions and session_list as public wire messages', () => {
+    const request: ListSessionsMessage = {
+      type: 'list_sessions',
+      limit: 25,
+      before: {sessionId: 'older', updatedAt: '2026-01-01T00:00:00.000Z'},
+    };
+    const row: SessionSummaryFrame = {
+      sessionId: 's1',
+      createdAt: '2026-01-01T00:00:00.000Z',
+      updatedAt: '2026-01-02T00:00:00.000Z',
+      entryCount: 3,
+    };
+    const response: SessionListMessage = {type: 'session_list', sessions: [row]};
+
+    const incoming: IncomingMessage = request;
+    const outgoing: OutgoingMessage = response;
+
+    expect({incoming, outgoing, validation: validateMessage(request)}).toEqual({
+      incoming: request,
+      outgoing: response,
+      validation: {valid: true, data: request},
+    });
+  });
+});
